INSERT INTO post ("id","format","status","visibility","pinned_at","featured_at","title","url","body","body_html","body_text","quote_text","summary","rating","reply_to_id","thread_id","deleted_at","published_at","last_activity_at","created_at","updated_at") VALUES('019ce8cd-4fb6-7aec-bbf3-bd0bd775aa12','note','published','public',NULL,NULL,NULL,NULL,'{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The best writing happens when you stop trying to sound smart and just say what you mean. Every draft gets better when you cut the clever parts."}]}]}','<p>The best writing happens when you stop trying to sound smart and just say what you mean. Every draft gets better when you cut the clever parts.</p>','The best writing happens when you stop trying to sound smart and just say what you mean. Every draft gets better when you cut the clever parts.',NULL,NULL,NULL,NULL,'019ce8cd-4fb6-7aec-bbf3-bd0bd775aa12',NULL,1773432295,1773432295,1773432295,1773432295);
INSERT INTO post ("id","format","status","visibility","pinned_at","featured_at","title","url","body","body_html","body_text","quote_text","summary","rating","reply_to_id","thread_id","deleted_at","published_at","last_activity_at","created_at","updated_at") VALUES('019ce8cd-5502-74a3-86d2-f0e993c06e5b','note','published','public',NULL,NULL,NULL,NULL,'{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Started waking up an hour earlier this week. Not to be productive — just to have a window where nobody expects anything from me. Coffee, silence, and whatever my mind wants to do. Turns out it usually wants to stare out the window for a while, and that''s fine."}]}]}','<p>Started waking up an hour earlier this week. Not to be productive — just to have a window where nobody expects anything from me. Coffee, silence, and whatever my mind wants to do. Turns out it usually wants to stare out the window for a while, and that&#39;s fine.</p>','Started waking up an hour earlier this week. Not to be productive — just to have a window where nobody expects anything from me. Coffee, silence, and whatever my mind wants to do. Turns out it usually wants to stare out the window for a while, and that''s fine.',NULL,NULL,NULL,NULL,'019ce8cd-5502-74a3-86d2-f0e993c06e5b',NULL,1773432296,1773432296,1773432296,1773432296);
INSERT INTO post ("id","format","status","visibility","pinned_at","featured_at","title","url","body","body_html","body_text","quote_text","summary","rating","reply_to_id","thread_id","deleted_at","published_at","last_activity_at","created_at","updated_at") VALUES('019ce8cd-5a0b-77d2-805c-6a92b5dd146d','note','published','public',NULL,NULL,NULL,NULL,'{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Noticed that the local bookshop rearranged everything by color instead of genre. Chaotic, impractical, and honestly kind of beautiful. Sometimes the wrong system is the right one."}]}]}','<p>Noticed that the local bookshop rearranged everything by color instead of genre. Chaotic, impractical, and honestly kind of beautiful. Sometimes the wrong system is the right one.</p>','Noticed that the local bookshop rearranged everything by color instead of genre. Chaotic, impractical, and honestly kind of beautiful. Sometimes the wrong system is the right one.',NULL,NULL,NULL,NULL,'019ce8cd-5a0b-77d2-805c-6a92b5dd146d',NULL,1773432297,1773432297,1773432297,1773432297);
INSERT INTO post ("id","format","status","visibility","pinned_at","featured_at","title","url","body","body_html","body_text","quote_text","summary","rating","reply_to_id","thread_id","deleted_at","published_at","last_activity_at","created_at","updated_at") VALUES('019ce8cd-e659-7237-b141-3b28d4d51f2d','note','published','public',1773432422,1773432422,'Why I Still Blog in 2026',NULL,'{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Everyone asks why I bother maintaining a personal blog when social media exists. The answer is simple: "},{"type":"text","text":"ownership","marks":[{"type":"bold"}]},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The case for your own space"}]},{"type":"paragraph","content":[{"type":"text","text":"Social platforms come and go. MySpace, Vine, the old Twitter — all either dead or unrecognizable. But a personal site? That stays as long as you want it to."}]},{"type":"paragraph","content":[{"type":"text","text":"Here''s what a blog gives you that no platform can:"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Full control","marks":[{"type":"bold"}]},{"type":"text","text":" over your content and presentation"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"No algorithm","marks":[{"type":"bold"}]},{"type":"text","text":" deciding who sees your work"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Permanent URLs","marks":[{"type":"bold"}]},{"type":"text","text":" that don''t break when a company pivots"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A creative outlet","marks":[{"type":"bold"}]},{"type":"text","text":" that belongs entirely to you"}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The tools have never been better"}]},{"type":"paragraph","content":[{"type":"text","text":"Setting up a blog used to mean wrestling with PHP and shared hosting. Now you can deploy a static site in minutes, or run something like Jant on Cloudflare Workers with zero server management."}]},{"type":"codeBlock","content":[{"type":"text","text":"npx create-jant my-blog\ncd my-blog && npm run dev"}],"attrs":{"language":"bash"}},{"type":"paragraph","content":[{"type":"text","text":"That''s it. You''re writing."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Write for yourself first"}]},{"type":"paragraph","content":[{"type":"text","text":"The best blogs aren''t optimized for engagement. They''re just one person thinking out loud — sharing what they''ve learned, what they''re curious about, what they can''t stop thinking about."}]},{"type":"paragraph","content":[{"type":"text","text":"If even one person stumbles across your post and finds it useful, that''s a win. But even if nobody reads it, you''ve clarified your own thinking. And that''s worth more than any like count."}]}]}','<p>Everyone asks why I bother maintaining a personal blog when social media exists. The answer is simple: <strong>ownership</strong>.</p><h2>The case for your own space</h2><p>Social platforms come and go. MySpace, Vine, the old Twitter — all either dead or unrecognizable. But a personal site? That stays as long as you want it to.</p><p>Here&#39;s what a blog gives you that no platform can:</p><ul><li><p><strong>Full control</strong> over your content and presentation</p></li><li><p><strong>No algorithm</strong> deciding who sees your work</p></li><li><p><strong>Permanent URLs</strong> that don&#39;t break when a company pivots</p></li><li><p><strong>A creative outlet</strong> that belongs entirely to you</p></li></ul><h2>The tools have never been better</h2><p>Setting up a blog used to mean wrestling with PHP and shared hosting. Now you can deploy a static site in minutes, or run something like Jant on Cloudflare Workers with zero server management.</p><pre><code class="language-bash">npx create-jant my-blog
INSERT INTO post ("id","format","status","visibility","pinned_at","featured_at","title","url","body","body_html","body_text","quote_text","summary","rating","reply_to_id","thread_id","deleted_at","published_at","last_activity_at","created_at","updated_at") VALUES('019ce8cd-eb16-7323-9eda-619befc99f43','note','published','public',NULL,1773432424,'On Walking Without a Destination',NULL,'{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"There''s a particular kind of walk that has no purpose. No errand, no exercise goal, no podcast in your ears. Just movement."}]},{"type":"moreBreak"},{"type":"paragraph","content":[{"type":"text","text":"The Japanese have a word for it — "},{"type":"text","text":"sanpo","marks":[{"type":"italic"}]},{"type":"text","text":" (散歩) — which literally translates to \"scatter steps.\" I love that. Steps that scatter, that go wherever they go."}]},{"type":"paragraph","content":[{"type":"text","text":"I''ve been doing this every Sunday for the past year. No route planned, no step counter checked. Just walking until something catches my eye — a side street I''ve never noticed, a cat asleep on a warm car hood, the way light falls differently at 4pm in winter."}]},{"type":"paragraph","content":[{"type":"text","text":"It''s the closest thing I''ve found to meditation that doesn''t involve sitting still."}]}]}','<p>There&#39;s a particular kind of walk that has no purpose. No errand, no exercise goal, no podcast in your ears. Just movement.</p><!--more--><p>The Japanese have a word for it — <em>sanpo</em> (散歩) — which literally translates to &quot;scatter steps.&quot; I love that. Steps that scatter, that go wherever they go.</p><p>I&#39;ve been doing this every Sunday for the past year. No route planned, no step counter checked. Just walking until something catches my eye — a side street I&#39;ve never noticed, a cat asleep on a warm car hood, the way light falls differently at 4pm in winter.</p><p>It&#39;s the closest thing I&#39;ve found to meditation that doesn&#39;t involve sitting still.</p>','There''s a particular kind of walk that has no purpose. No errand, no exercise goal, no podcast in your ears. Just movement. The Japanese have a word for it —  sanpo  (散歩) — which literally translates to "scatter steps." I love that. Steps that scatter, that go wherever they go. I''ve been doing this every Sunday for the past year. No route planned, no step counter checked. Just walking until something catches my eye — a side street I''ve never noticed, a cat asleep on a warm car hood, the way light falls differently at 4pm in winter. It''s the closest thing I''ve found to meditation that doesn''t involve sitting still.',NULL,'There''s a particular kind of walk that has no purpose. No errand, no exercise goal, no podcast in your ears. Just movement.',NULL,NULL,'019ce8cd-eb16-7323-9eda-619befc99f43',NULL,1773432335,1773432335,1773432335,1773432424);
INSERT INTO post ("id","format","status","visibility","pinned_at","featured_at","title","url","body","body_html","body_text","quote_text","summary","rating","reply_to_id","thread_id","deleted_at","published_at","last_activity_at","created_at","updated_at") VALUES('019ce8ce-340a-74bc-98dd-d5130505fb47','link','published','public',NULL,NULL,'SQLite on the Edge: D1 at Cloudflare','https://blog.cloudflare.com/introducing-d1','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Cloudflare D1 brings SQLite to the edge. For small projects like personal blogs, this is a game-changer — your database lives right next to your code, no connection pooling, no cold starts. It''s what makes running Jant on Workers practical."}]}]}','<p>Cloudflare D1 brings SQLite to the edge. For small projects like personal blogs, this is a game-changer — your database lives right next to your code, no connection pooling, no cold starts. It&#39;s what makes running Jant on Workers practical.</p>','Cloudflare D1 brings SQLite to the edge. For small projects like personal blogs, this is a game-changer — your database lives right next to your code, no connection pooling, no cold starts. It''s what makes running Jant on Workers practical.',NULL,NULL,NULL,NULL,'019ce8ce-340a-74bc-98dd-d5130505fb47',NULL,1773432353,1773432353,1773432353,1773432353);
INSERT INTO post ("id","format","status","visibility","pinned_at","featured_at","title","url","body","body_html","body_text","quote_text","summary","rating","reply_to_id","thread_id","deleted_at","published_at","last_activity_at","created_at","updated_at") VALUES('019ce8ce-38c0-7ed2-98c3-04e11fcae771','link','published','public',NULL,NULL,'Drizzle ORM — TypeScript ORM That Feels Like SQL','https://orm.drizzle.team','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"After years of fighting ORMs that try to hide SQL, Drizzle is refreshing. It gives you type safety without pretending the database doesn''t exist. The schema-as-code approach means your TypeScript types and your database schema are always in sync."}]}]}','<p>After years of fighting ORMs that try to hide SQL, Drizzle is refreshing. It gives you type safety without pretending the database doesn&#39;t exist. The schema-as-code approach means your TypeScript types and your database schema are always in sync.</p>','After years of fighting ORMs that try to hide SQL, Drizzle is refreshing. It gives you type safety without pretending the database doesn''t exist. The schema-as-code approach means your TypeScript types and your database schema are always in sync.',NULL,NULL,NULL,NULL,'019ce8ce-38c0-7ed2-98c3-04e11fcae771',NULL,1773432355,1773432355,1773432355,1773432355);
INSERT INTO post ("id","format","status","visibility","pinned_at","featured_at","title","url","body","body_html","body_text","quote_text","summary","rating","reply_to_id","thread_id","deleted_at","published_at","last_activity_at","created_at","updated_at") VALUES('019ce8ce-3f7f-7894-8e57-30af7510c8df','link','published','public',NULL,NULL,'The Technium: 1,000 True Fans','https://kk.org/thetechnium/1000-true-fans/','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Kevin Kelly''s 2008 essay keeps proving itself right. You don''t need millions of followers — you need a thousand people who genuinely care about what you make. Still the most important thing I''ve read about creative sustainability."}]}]}','<p>Kevin Kelly&#39;s 2008 essay keeps proving itself right. You don&#39;t need millions of followers — you need a thousand people who genuinely care about what you make. Still the most important thing I&#39;ve read about creative sustainability.</p>','Kevin Kelly''s 2008 essay keeps proving itself right. You don''t need millions of followers — you need a thousand people who genuinely care about what you make. Still the most important thing I''ve read about creative sustainability.',NULL,NULL,NULL,NULL,'019ce8ce-3f7f-7894-8e57-30af7510c8df',NULL,1773432356,1773432356,1773432356,1773432356);
INSERT INTO post ("id","format","status","visibility","pinned_at","featured_at","title","url","body","body_html","body_text","quote_text","summary","rating","reply_to_id","thread_id","deleted_at","published_at","last_activity_at","created_at","updated_at") VALUES('019ce8ce-7641-7867-ad27-bbfbbf152429','quote','published','public',NULL,NULL,'Kurt Vonnegut','https://en.wikipedia.org/wiki/Mother_Night','{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"From "},{"type":"text","text":"Mother Night","marks":[{"type":"italic"}]},{"type":"text","text":" (1961). A line that hits differently every time I re-read it."}]}]}','<p>From <em>Mother Night</em> (1961). A line that hits differently every time I re-read it.</p>','From  Mother Night  (1961). A line that hits differently every time I re-read it.','We are what we pretend to be, so we must be careful about what we pretend to be.',NULL,NULL,NULL,'019ce8ce-7641-7867-ad27-bbfbbf152429',NULL,1773432370,1773432370,1773432370,1773432370);
INSERT INTO post ("id","format","status","visibility","pinned_at","featured_at","title","url","body","body_html","body_text","quote_text","summary","rating","reply_to_id","thread_id","deleted_at","published_at","last_activity_at","created_at","updated_at") VALUES('019ce8ce-7b8b-7a25-817a-6d9f24c99924','quote','published','public',NULL,NULL,'Stafford Beer',NULL,'{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"POSIWID — one of the most useful mental models for understanding organizations. Don''t look at mission statements. Look at outcomes."}]}]}','<p>POSIWID — one of the most useful mental models for understanding organizations. Don&#39;t look at mission statements. Look at outcomes.</p>','POSIWID — one of the most useful mental models for understanding organizations. Don''t look at mission statements. Look at outcomes.','The purpose of a system is what it does. There is, after all, no point in claiming that the purpose of a system is to do what it constantly fails to do.',NULL,NULL,NULL,'019ce8ce-7b8b-7a25-817a-6d9f24c99924',NULL,1773432372,1773432372,1773432372,1773432372);
INSERT INTO post ("id","format","status","visibility","pinned_at","featured_at","title","url","body","body_html","body_text","quote_text","summary","rating","reply_to_id","thread_id","deleted_at","published_at","last_activity_at","created_at","updated_at") VALUES('019ce8ce-809b-7754-b09c-771e01566f63','quote','published','public',NULL,NULL,'George R.R. Martin',NULL,'{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"From "},{"type":"text","text":"A Dance with Dragons","marks":[{"type":"italic"}]},{"type":"text","text":". The simplest argument for reading I''ve ever encountered."}]}]}','<p>From <em>A Dance with Dragons</em>. The simplest argument for reading I&#39;ve ever encountered.</p>','From  A Dance with Dragons . The simplest argument for reading I''ve ever encountered.','A reader lives a thousand lives before he dies. The man who never reads lives only one.',NULL,5,NULL,'019ce8ce-809b-7754-b09c-771e01566f63',NULL,1773432373,1773432373,1773432373,1773432373);
