INSERT INTO post ("id","format","status","visibility","pinned_at","featured_at","title","url","body","body_html","body_text","quote_text","summary","rating","reply_to_id","thread_id","deleted_at","published_at","last_activity_at","created_at","updated_at") VALUES('019ce8ce-bd2c-772b-ad0b-4875ba22705d','note','published','public',NULL,NULL,'Weekend Wandering',NULL,'{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Took the long way home through a part of the city I never visit. Found these two scenes within a block of each other — proof that you don''t need to travel far to find something worth looking at."}]}]}','<p>Took the long way home through a part of the city I never visit. Found these two scenes within a block of each other — proof that you don&#39;t need to travel far to find something worth looking at.</p>','Took the long way home through a part of the city I never visit. Found these two scenes within a block of each other — proof that you don''t need to travel far to find something worth looking at.',NULL,'Took the long way home through a part of the city I never visit. Found these two scenes within a block of each other — proof that you don''t need to travel far to find something worth looking at.',NULL,NULL,'019ce8ce-bd2c-772b-ad0b-4875ba22705d',NULL,1773432388,1773432388,1773432388,1773432388);
INSERT INTO post ("id","format","status","visibility","pinned_at","featured_at","title","url","body","body_html","body_text","quote_text","summary","rating","reply_to_id","thread_id","deleted_at","published_at","last_activity_at","created_at","updated_at") VALUES('019ce8ce-d6d8-7fda-a5df-c2da2bef5ade','note','published','public',NULL,NULL,NULL,NULL,'{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A thread on "},{"type":"text","text":"building in public","marks":[{"type":"bold"}]},{"type":"text","text":" — something I''ve been thinking about a lot lately as I work on this site. 🧵"}]}]}','<p>A thread on <strong>building in public</strong> — something I&#39;ve been thinking about a lot lately as I work on this site. 🧵</p>','A thread on  building in public  — something I''ve been thinking about a lot lately as I work on this site. 🧵',NULL,NULL,NULL,NULL,'019ce8ce-d6d8-7fda-a5df-c2da2bef5ade',NULL,1773432395,1773432412,1773432395,1773432395);
INSERT INTO post ("id","format","status","visibility","pinned_at","featured_at","title","url","body","body_html","body_text","quote_text","summary","rating","reply_to_id","thread_id","deleted_at","published_at","last_activity_at","created_at","updated_at") VALUES('019ce8cf-0db9-7649-a36c-6a942d202aa8','note','published',NULL,NULL,NULL,NULL,NULL,'{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The conventional wisdom is to share your progress constantly — every commit, every design iteration, every decision. But I''ve found that too much sharing "},{"type":"text","text":"while building","marks":[{"type":"italic"}]},{"type":"text","text":" actually slows me down. It shifts my focus from \"is this good?\" to \"does this look good?\""}]}]}','<p>The conventional wisdom is to share your progress constantly — every commit, every design iteration, every decision. But I&#39;ve found that too much sharing <em>while building</em> actually slows me down. It shifts my focus from &quot;is this good?&quot; to &quot;does this look good?&quot;</p>','The conventional wisdom is to share your progress constantly — every commit, every design iteration, every decision. But I''ve found that too much sharing  while building  actually slows me down. It shifts my focus from "is this good?" to "does this look good?"',NULL,NULL,NULL,'019ce8ce-d6d8-7fda-a5df-c2da2bef5ade','019ce8ce-d6d8-7fda-a5df-c2da2bef5ade',NULL,1773432409,1773432409,1773432409,1773432409);
INSERT INTO post ("id","format","status","visibility","pinned_at","featured_at","title","url","body","body_html","body_text","quote_text","summary","rating","reply_to_id","thread_id","deleted_at","published_at","last_activity_at","created_at","updated_at") VALUES('019ce8cf-13df-7459-85a6-65e7fb8f9421','note','published',NULL,NULL,NULL,NULL,NULL,'{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"What works better for me: build in private, "},{"type":"text","text":"write","marks":[{"type":"italic"}]},{"type":"text","text":" in public. Finish a feature, let it settle, then write about what I learned. The writing becomes the artifact — not a stream-of-consciousness progress bar, but a considered reflection."}]}]}','<p>What works better for me: build in private, <em>write</em> in public. Finish a feature, let it settle, then write about what I learned. The writing becomes the artifact — not a stream-of-consciousness progress bar, but a considered reflection.</p>','What works better for me: build in private,  write  in public. Finish a feature, let it settle, then write about what I learned. The writing becomes the artifact — not a stream-of-consciousness progress bar, but a considered reflection.',NULL,NULL,NULL,'019ce8ce-d6d8-7fda-a5df-c2da2bef5ade','019ce8ce-d6d8-7fda-a5df-c2da2bef5ade',NULL,1773432411,1773432411,1773432411,1773432411);
INSERT INTO post ("id","format","status","visibility","pinned_at","featured_at","title","url","body","body_html","body_text","quote_text","summary","rating","reply_to_id","thread_id","deleted_at","published_at","last_activity_at","created_at","updated_at") VALUES('019ce8cf-19a1-7d16-9a75-017a9ac7299d','note','published',NULL,NULL,NULL,NULL,NULL,'{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"That''s partly why I built this site the way I did — threads for connected thoughts, long posts for deeper dives, and no engagement metrics pulling me toward performance. The audience is future-me and anyone who happens to find it useful."}]}]}','<p>That&#39;s partly why I built this site the way I did — threads for connected thoughts, long posts for deeper dives, and no engagement metrics pulling me toward performance. The audience is future-me and anyone who happens to find it useful.</p>','That''s partly why I built this site the way I did — threads for connected thoughts, long posts for deeper dives, and no engagement metrics pulling me toward performance. The audience is future-me and anyone who happens to find it useful.',NULL,NULL,NULL,'019ce8ce-d6d8-7fda-a5df-c2da2bef5ade','019ce8ce-d6d8-7fda-a5df-c2da2bef5ade',NULL,1773432412,1773432412,1773432412,1773432412);
